import {LitElement,html,css,nothing} from 'lit';
import {common,icon} from './components.js';
import {M3BaseCard} from './cards.js';
import {validateConfig,perform} from './ha.js';
import {translate,locale} from './localize.js';

export function renderCard(card,hass,parent){
  const c={...card,language:card.language??parent.language,appearance:{...parent.appearance,...card.appearance}};
  if(card.kind==='climate')return html`<ha-m3-climate-card .hass=${hass} .cardConfig=${c}></ha-m3-climate-card>`;
  if(card.kind==='camera')return html`<ha-m3-camera-card .hass=${hass} .cardConfig=${c}></ha-m3-camera-card>`;
  return html`<ha-m3-device-card .hass=${hass} .cardConfig=${c}></ha-m3-device-card>`;
}
// Lit property setter keeps setConfig validation shared with Lovelace cards.
Object.defineProperty(M3BaseCard.prototype,'cardConfig',{set(value){if(this._incomingConfig!==value){this._incomingConfig=value;this.setConfig(value);}}});

export class M3Panel extends M3BaseCard{
  static properties={...M3BaseCard.properties,narrow:{type:Boolean},panel:{attribute:false},route:{attribute:false},_page:{state:true},_room:{state:true}};
  static styles=[common,css`
    :host{display:block;min-height:100%;background:var(--md-sys-color-surface);--md-ref-typeface-plain:'HA M3 Roboto',Roboto,Arial,sans-serif;--md-ref-typeface-brand:var(--md-ref-typeface-plain)}
    .layout{display:grid;grid-template-columns:80px minmax(0,1fr);min-height:100%}.rail{background:var(--md-sys-color-surface);display:flex;align-items:center;flex-direction:column;padding:20px 8px;gap:12px}.brand{height:48px;display:grid;place-items:center;color:var(--md-sys-color-primary);margin-bottom:16px}
    .nav-item{background:transparent;border:0;padding:0 0 8px;min-width:64px;min-height:64px;display:flex;flex-direction:column;align-items:center;gap:4px;color:var(--md-sys-color-on-surface-variant);font-size:12px;line-height:16px;font-weight:500;letter-spacing:.5px;cursor:pointer;border-radius:16px;outline:0}.indicator{position:relative;width:56px;height:32px;display:grid;place-items:center;border-radius:16px;overflow:hidden}.nav-item[aria-current=page]{color:var(--md-sys-color-on-surface)}.nav-item[aria-current=page] .indicator{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container)}.nav-item[aria-current=page] .symbol{font-variation-settings:'FILL' 1}.nav-item:hover .indicator::after,.nav-item:active .indicator::after{content:'';position:absolute;inset:0;background:currentColor;opacity:.08}.nav-item:active .indicator::after{opacity:.1}.nav-item:focus-visible{outline:3px solid var(--md-sys-color-secondary);outline-offset:2px}
    main{min-width:0;padding:0 24px 24px;width:100%;max-width:1504px;margin:0 auto}.appbar{height:64px;display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.appbar h1{font-size:22px;line-height:28px}.appbar .leading{display:flex;align-items:center;gap:12px}.menu{margin-left:-12px}.appbar .actions{display:flex;gap:8px}.page-heading{margin-bottom:24px;display:flex;gap:16px;align-items:center}.page-heading h2{font-size:28px;line-height:36px;font-weight:500}.page-heading p{font-size:14px;line-height:20px;margin-top:4px;color:var(--md-sys-color-on-surface-variant)}
    .home-grid{display:grid;grid-template-columns:minmax(0,1.32fr) minmax(0,1fr);gap:24px;align-items:start}.stack{display:grid;gap:16px;min-width:0}.rooms{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(280px,100%),1fr));gap:16px}.room{width:100%;position:relative;padding:24px;display:flex;flex-direction:column;align-items:flex-start;gap:12px;text-align:left;background:var(--md-sys-color-surface-container);border:0;border-radius:28px;color:var(--md-sys-color-on-surface);min-height:140px;cursor:pointer}.room strong{font-size:22px;line-height:28px;letter-spacing:0;font-weight:400}.room small{color:var(--md-sys-color-on-surface-variant);font-size:14px;line-height:20px}.room .symbol{color:var(--md-sys-color-primary)}.room:hover{background:var(--md-sys-color-surface-container-high)}.room:focus-visible{outline:3px solid var(--md-sys-color-secondary);outline-offset:2px}
    .device-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(360px,100%),1fr));gap:16px}.camera-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(420px,100%),1fr));gap:24px}.links{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-top:24px;border-top:1px solid var(--md-sys-color-outline-variant);padding-top:8px}.bottom{display:none;position:sticky;bottom:0;z-index:3}.empty{padding:40px 24px;text-align:center;color:var(--md-sys-color-on-surface-variant)}.mobile-menu{display:none}.page-heading{scroll-margin-top:144px}
    @media(max-width:1000px){.home-grid{grid-template-columns:1fr}.home-grid{max-width:680px;margin:0 auto}}@media(max-width:599px){.layout{display:block}.rail{display:none}main{padding:0 16px 24px}.appbar{margin-bottom:16px}.mobile-menu{display:inline-flex}.bottom{display:flex;justify-content:space-around;align-items:center;min-height:80px;padding:12px 8px;background:var(--md-sys-color-surface-container)}.bottom .nav-item{min-width:80px;min-height:56px;padding:0}.bottom .indicator{width:64px}.page-heading{margin-bottom:16px}.page-heading h2{font-size:24px;line-height:32px}.home-grid{gap:16px}.nav-item{flex:1}}
    @media(min-width:600px){.mobile-menu{display:none}}@media(max-width:355px){main{padding-left:12px;padding-right:12px}.page-heading{flex-wrap:wrap}}
    .layout.embedded{grid-template-columns:minmax(0,1fr)}.embedded main{padding-top:16px}.section-nav{display:flex;align-items:center;gap:8px;margin-bottom:24px;min-height:56px}.section-nav .nav-item{min-height:48px;min-width:0;flex-direction:row;gap:8px;padding:0 16px;border-radius:24px;font-size:14px;line-height:20px;letter-spacing:.1px}.section-nav .indicator{width:24px;height:24px;overflow:visible}.section-nav .nav-item[aria-current=page]{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container)}.section-nav .nav-item[aria-current=page] .indicator{background:transparent}.section-nav .nav-item:hover{background:var(--md-sys-color-surface-container-highest)}.section-nav .nav-item[aria-current=page]:hover{background:var(--md-sys-color-secondary-container)}.section-actions{margin-left:auto;display:flex;gap:8px}.embedded .page-heading{scroll-margin-top:144px}
    @media(max-width:599px){.section-nav{display:none}.embedded main{padding-top:24px}.embedded .page-heading{scroll-margin-top:80px}}
  `];
  constructor(){super();this._page='home';this._room=null;this.narrow=false;}
  setConfig(config){this._config=validateConfig(config,'panel');}
  willUpdate(changed){if(changed.has('panel')&&this.panel?.config)this.setConfig(this.panel.config);if(changed.has('route')&&this.route?.path){const page=this.route.path.split('/').filter(Boolean)[0];if(['home','rooms','cameras'].includes(page))this._page=page;}super.willUpdate(changed);}
  getGridOptions(){return{columns:'full',rows:'auto'};}
  getCardSize(){return 16;}
  get embedded(){return false;}
  async page(page,room=null){this._page=page;this._room=room;await this.updateComplete;const heading=this.renderRoot.querySelector('.page-heading');heading?.scrollIntoView({block:'start',behavior:'instant'});}
  nav(){return[['home','home'],['rooms','meeting_room'],['cameras','videocam']].map(([page,symbol])=>html`<button class="nav-item" type="button" aria-current=${this._page===page?'page':nothing} @click=${()=>this.page(page)}><span class="indicator">${icon(symbol)}</span><span>${this.t(page)}</span></button>`);}
  render(){
    const c=this._config,home=c.home||{},rooms=c.rooms||[],cards=home.cards||[],primary=cards.filter(card=>card.kind==='climate'),secondary=cards.filter(card=>card.kind!=='climate'),room=rooms.find(r=>r.id===this._room),cameras=c.cameras||cards.filter(card=>card.kind==='camera');
    const actions=html`${(c.header_actions||[]).map(a=>html`<ha-m3-button kind="text" .label=${a.name} .icon=${a.icon||'settings'} @click=${()=>this.run(a.action)}></ha-m3-button>`)}`;
    return html`<div class=${this.embedded?'layout embedded':'layout'}>${this.embedded?nothing:html`<nav class="rail" aria-label=${this.t('home')}><div class="brand">${icon('home')}</div>${this.nav()}</nav>`}<main>${this.embedded?html`<nav class="section-nav" aria-label=${c.title||this.t('home')}>${this.nav()}<div class="section-actions">${actions}</div></nav>`:html`<header class="appbar"><div class="leading"><ha-m3-button class="menu mobile-menu" kind="text" icon="menu" .label=${this.t('menu')} @click=${()=>this.dispatchEvent(new CustomEvent('hass-toggle-menu',{bubbles:true,composed:true}))}></ha-m3-button><h1>${c.title||this.t('home')}</h1></div><div class="actions">${actions}</div></header>`}
    ${this._page==='home'?html`<header class="page-heading"><div><h2>${home.title||this.t('home')}</h2>${home.subtitle?html`<p>${home.subtitle}</p>`:nothing}</div></header><div class="home-grid"><div class="stack">${primary.map(card=>renderCard(card,this.hass,c))}</div><div class="stack">${secondary.map(card=>renderCard(card,this.hass,c))}</div></div>${!cards.length?html`<div class="empty">${this.t('empty')}</div>`:nothing}`:nothing}
    ${this._page==='rooms'?html`<header class="page-heading">${room?html`<ha-m3-button kind="text" icon="arrow_back" .label=${this.t('rooms')} @click=${()=>this.page('rooms')}></ha-m3-button>`:nothing}<h2>${room?.name||this.t('rooms')}</h2></header>${room?html`<div class="device-grid">${(room.cards||[]).map(card=>renderCard(card,this.hass,c))}</div>`:html`<div class="rooms">${rooms.map(r=>html`<button type="button" class="room" @click=${()=>this.page('rooms',r.id)}>${icon(r.icon||'meeting_room')}<strong>${r.name}</strong><small>${r.description||''}</small></button>`)}</div>`}${!rooms.length?html`<div class="empty">${this.t('empty')}</div>`:nothing}`:nothing}
    ${this._page==='cameras'?html`<header class="page-heading"><h2>${this.t('cameras')}</h2></header><div class="camera-grid">${cameras.map(card=>renderCard({...card,kind:'camera'},this.hass,c))}</div>`:nothing}
    ${c.links?.length?html`<footer class="links">${c.links.map(link=>html`<ha-m3-button kind="text" .icon=${link.icon||''} @click=${()=>this.run(link.action)}>${link.name}</ha-m3-button>`)}</footer>`:nothing}${this.feedback()}</main></div><nav class="bottom" aria-label=${this.t('home')}>${this.nav()}</nav>`;
  }
}
customElements.define('ha-m3-panel',M3Panel);
export class M3Dashboard extends M3Panel{get embedded(){return true;}}
customElements.define('ha-m3-dashboard',M3Dashboard);
